import json
def solve(g,keep_noise=False):
    a=np.array(g); bg=a.flat[0]
    shapes={v:list(np.argwhere(a==v)) for v in sorted(set(a.flat)-{bg})}
    noise=None
    for v,pts in shapes.items():
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        if len(pts)==(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1): noise=v
    tgt=[v for v in shapes if v!=noise][0]
    C=((sum(p[0] for p in shapes[noise])/len(shapes[noise]), sum(p[1] for p in shapes[noise])/len(shapes[noise])))
    Pt=set(map(tuple,shapes[tgt]))
    def refl(cells): 
        cr,cc=C; return {(int(2*cr-x),int(2*cc-y)) for x,y in cells}|{(int(x),int(2*cc-y)) for x,y in cells}|{(int(2*cr-x),int(y)) for x,y in cells}|set(cells)
    res=[[a[i][j] for j in range(len(a[0]))] for i in range(len(a))]
    for r,c in refl(Pt):
        if 0<=r<len(a) and 0<=c<len(a[0]) and (not keep_noise or a[r][c]!=tgt and (tgt not in () or True)):
            if keep_noise: res[r][c]=tgt
            else: res[r][c]=tgt  # always paint (demo shows original shape kept anyway since it's part of stamp)
    return res
